source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    color = next(c for c, _ in counts.most_common() if c not in (0, 1, 2, 5, 9))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = {(r-r0, c-c0) for r, c in pts}
    mh, mw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-mh+1):
        for c in range(w-mw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out
'''
